/// Live object counts of one engine: Filament's `Engine::get*Count()`,
/// the renderable / light / transform component counts, and the process-wide
/// entity count (entities are not per engine). Lets tests prove that a
/// viewport sharing an engine left nothing behind, and that a second viewport
/// on the same asset uploaded no new texture.
final class filament_engine_resource_counts_t extends ffi.Struct {
  @ffi.Int64()
  external int textures;

  @ffi.Int64()
  external int materials;

  @ffi.Int64()
  external int vertex_buffers;

  @ffi.Int64()
  external int index_buffers;

  @ffi.Int64()
  external int buffer_objects;

  @ffi.Int64()
  external int skinning_buffers;

  @ffi.Int64()
  external int morph_target_buffers;

  @ffi.Int64()
  external int instance_buffers;

  @ffi.Int64()
  external int views;

  @ffi.Int64()
  external int scenes;

  @ffi.Int64()
  external int swap_chains;

  @ffi.Int64()
  external int indirect_lights;

  @ffi.Int64()
  external int skyboxes;

  @ffi.Int64()
  external int color_gradings;

  @ffi.Int64()
  external int render_targets;

  @ffi.Int64()
  external int renderables;

  @ffi.Int64()
  external int lights;

  @ffi.Int64()
  external int transforms;

  @ffi.Int64()
  external int entities;
}

