  @ffi.Array.multi([256])
  external ffi.Array<ffi.Char> name;

  @ffi.Int32()
  external int type;

  @ffi.Uint32()
  external int vendor_id;

  @ffi.Uint32()
  external int device_id;

  @ffi.Uint32()
  external int api_version;

  @ffi.Int32()
  external int index;
}

/// Device-local memory of the GPU an engine renders on, as `VK_EXT_memory_budget`
/// reports it. `device_local_usage` is this *process's* usage of
/// the device-local heaps, `device_local_budget` what the driver says the
/// process can use, `device_local_size` the heaps' size; all bytes, summed
/// over every `VK_MEMORY_HEAP_DEVICE_LOCAL_BIT` heap.
final class filament_gpu_memory_t extends ffi.Struct {
  @ffi.Uint64()
  external int device_local_usage;

  @ffi.Uint64()
  external int device_local_budget;

  @ffi.Uint64()
  external int device_local_size;

  @ffi.Int32()
  external int heap_count;
}

